import {libraryTopics,libraryFormats,libraryCategories,libraryLanguages,libraryPdfLimit} from './library-schema.js';
const input=(t,h,n,k,v='',type='text',extra='')=>`<label>${h(t(k))}<input name="${n}" type="${type}" value="${h(v)}" ${extra}></label>`;
const area=(t,h,n,k,v='',max=1000,required=false)=>`<label>${h(t(k))}<textarea name="${n}" maxlength="${max}" ${required?'required':''}>${h(v)}</textarea></label>`;
const select=(t,h,n,k,options,v='')=>`<label>${h(t(k))}<select name="${n}">${options.map(([id,label])=>`<option value="${h(id)}" ${id===v?'selected':''}>${h(label)}</option>`).join('')}</select></label>`;
const hidden=(h,n,v)=>`<input type="hidden" name="${n}" value="${h(v)}">`;
const form=(t,h,op,body,id='',label='save')=>`<form class="stack" data-form="programs">${hidden(h,'module','library')}${hidden(h,'operation',op)}${id?hidden(h,'id',id):''}${body}<button class="primary" type="submit">${h(t(label))}</button></form>`;
const action=(t,h,btn,op,id,key,attrs='')=>btn(t(key),'programAction',`data-module="library" data-op="${op}" data-id="${h(id)}" ${attrs}`,'secondary');
const detail=(key,title,body,edit=false)=>`<details class="card library-disclosure${edit?' library-edit':''}" data-disclosure-key="library:${key}"><summary><strong>${title}</strong></summary><div class="stack library-body">${body}</div></details>`;
const topics=t=>libraryTopics.map(x=>[x,t('libraryTopic_'+x)]);
const formats=t=>libraryFormats.map(x=>[x,t('libraryFormat_'+x)]);
const categories=t=>libraryCategories.map(x=>[x,t(x==='book'?'programBook':'programGuide')]);
const langs=t=>libraryLanguages.map(x=>[x,t('lang_'+x)]);
function fields(t,h,r){return hidden(h,'scope','public')+input(t,h,'title','programTitle',r?.title,'text','required maxlength="100"')+input(t,h,'author','programAuthor',r?.author,'text','required maxlength="100"')+select(t,h,'category','programCategory',categories(t),r?.category||'book')+select(t,h,'topic','libraryTopic',topics(t),r?.topic||'other')+select(t,h,'language','language',langs(t),r?.language||'en')+select(t,h,'format','libraryFormat',formats(t),r?.format||'text')+area(t,h,'description','programDescription',r?.description,2000,true)+area(t,h,'content','programContent',r?.content,12000)+input(t,h,'rightsNote','programRights',r?.rightsNote,'text','required maxlength="200"')+`<label class="check-row"><input name="rights" type="checkbox" required>${h(t('programRightsConfirm'))}</label><p class="muted">${h(t('libraryDraftHint'))}</p>`}
function pdfPanel(t,h,btn,r){return `<p class="muted">${h(t('libraryPdfHint'))}</p>${r.pdf?`<div class="row space wrap"><b>PDF · ${(r.pdf.size/1048576).toFixed(2)} MB</b><a href="/api/library-pdf?id=${encodeURIComponent(r.id)}" class="secondary">${h(t('programDownload'))}</a>${action(t,h,btn,'libraryPdfRemove',r.id,'remove')}</div>`:''}${r.format!=='text'?`<form class="stack" data-form="libraryUpload">${hidden(h,'id',r.id)}<label>${h(t('libraryUploadPdf'))}<input name="file" type="file" accept=".pdf,application/pdf" required></label><button type="submit" class="primary">${h(t('libraryUploadPdf'))}</button><small>${libraryPdfLimit/1048576} MB</small></form>`:''}`}
export function libraryPage({state,t,h,btn,filter={}}){
  const p=state.programs,l=p.library||{canSave:false,preferences:[]},all=p.items.filter(r=>r.module==='library'),prefs=new Map(l.preferences.map(x=>[x.itemId,x]));
  const filters=`<form class="row wrap" data-form="programFilter">${hidden(h,'module','library')}${input(t,h,'query','programSearch',filter.query||'','search')}${select(t,h,'language','language',[['',t('all')],...langs(t)],filter.language||'')}${select(t,h,'category','programCategory',[['',t('all')],...categories(t)],filter.category||'')}${select(t,h,'topic','libraryTopic',[['',t('all')],...topics(t)],filter.topic||'')}${select(t,h,'format','libraryFormat',[['',t('all')],...formats(t)],filter.format||'')}${select(t,h,'view','libraryView',[['all',t('all')],...(l.canSave?[['favorites',t('libraryFavorites')],['reading',t('libraryReading')],['finished',t('libraryFinished')]]:[]),...(p.canAdmin?[['draft',t('programStatus_draft')],['published',t('programStatus_published')],['archived',t('programStatus_archived')]]:[])],filter.view||'all')}${select(t,h,'sort','librarySort',[['recent',t('libraryRecent')],['title',t('programTitle')]],filter.sort||'recent')}<button class="secondary" type="submit">${h(t('programSearch'))}</button></form>`;
  const q=(filter.query||'').trim().toLowerCase(),rows=all.filter(r=>{const pref=prefs.get(r.id),view=filter.view||'all';return (!filter.language||r.language===filter.language)&&(!filter.category||r.category===filter.category)&&(!filter.topic||r.topic===filter.topic)&&(!filter.format||r.format===filter.format)&&(!q||[r.title,r.author,r.description].some(v=>String(v).toLowerCase().includes(q)))&&(view==='all'||(view==='favorites'&&pref?.favorite)||(view==='reading'&&pref?.progress>0&&pref.progress<100)||(view==='finished'&&pref?.progress===100)||r.status===view)}).sort((a,b)=>filter.sort==='title'?a.title.localeCompare(b.title):b.updatedAt-a.updatedAt||a.title.localeCompare(b.title));
  const metrics=[['libraryAvailable',all.filter(x=>x.status==='published').length],...[...(l.canSave?[['libraryFavorites',l.preferences.filter(x=>x.favorite).length],['libraryFinished',l.preferences.filter(x=>x.progress===100).length]]:[]),...(p.canAdmin?[['programStatus_draft',all.filter(x=>x.status==='draft').length],['programStatus_archived',all.filter(x=>x.status==='archived').length]]:[])]];
  const cards=rows.map(r=>{const pref=prefs.get(r.id),progress=pref?.progress??0,reader=`${r.content&&r.format!=='pdf'?`<p class="post-text library-text">${h(r.content)}</p>${action(t,h,btn,'download',r.id,'libraryDownloadText')}`:''}${r.pdf&&r.format!=='text'?`<a class="secondary" href="/api/library-pdf?id=${encodeURIComponent(r.id)}">${h(t('libraryDownloadPdf'))} · ${(r.pdf.size/1048576).toFixed(2)} MB</a>`:''}${l.canSave&&r.status==='published'?form(t,h,'libraryProgress',input(t,h,'progress','libraryProgress',progress,'number','min="0" max="100" step="1" required'),r.id):''}`;
    const manage=r.manage?`${detail(`edit:${h(r.id)}`,h(t('wellnessEdit')),form(t,h,'update',fields(t,h,r),r.id),true)}${detail(`pdf:${h(r.id)}`,h(t('libraryFiles')),pdfPanel(t,h,btn,r),true)}<div class="row wrap">${r.status==='draft'?action(t,h,btn,'publish',r.id,'programPublish'):action(t,h,btn,'draft',r.id,'programUnpublish')}${r.status!=='archived'?action(t,h,btn,'archive',r.id,'programArchive'):''}</div>`:'';
    const title=`<div class="library-cover"><span>MUSCLIVO</span><strong>${h(r.title)}</strong><small>${h(r.author)}</small></div><div class="stack"><div class="row wrap"><span class="badge">${h(t(r.category==='book'?'programBook':'programGuide'))}</span><span class="badge">${h(r.language.toUpperCase())}</span><span class="badge ${r.status==='published'?'green':'gold'}">${h(t('programStatus_'+r.status))}</span></div><h2>${h(r.title)}</h2><small>${h(r.author)} · ${h(t('libraryTopic_'+r.topic))} · ${h(t('libraryFormat_'+r.format))}</small><p>${h(r.description)}</p><small>${h(t('programRights'))}: ${h(r.rightsNote)}</small></div>`;
    return `<article class="card stack library-item">${title}${l.canSave&&r.status==='published'?`<div class="row wrap">${action(t,h,btn,'libraryFavorite',r.id,pref?.favorite?'libraryRemoveFavorite':'librarySaveFavorite',`data-favorite="${!pref?.favorite}"`)}${pref?action(t,h,btn,'libraryClear',r.id,'libraryClearReading'):''}</div><progress value="${progress}" max="100"></progress><small>${h(t('libraryProgress'))}: ${progress}%</small>`:''}${detail(`reader:${h(r.id)}`,h(t('libraryRead')),reader||`<p class="empty">${h(t('libraryEmptyDraft'))}</p>`)}${manage}</article>`;
  }).join('');
  return `<div class="stack library-pro"><div class="hero workspace-hero"><span class="eyebrow">MUSCLIVO LIVE / LIBRARY PRO</span><h1>${h(t('library'))}</h1><p>${h(t('libraryIntro'))}</p></div><p class="notice">${h(t('programLocalNotice'))}</p><div class="dashboard-metrics">${metrics.map(([k,v])=>`<div class="stat-box"><div class="stat green">${v}</div><small>${h(t(k))}</small></div>`).join('')}</div>${p.canAdmin?detail('new',h(t('libraryNewDraft')),form(t,h,'create',fields(t,h),undefined,'create'),true):''}<section class="card stack">${filters}</section><div class="grid library-grid">${cards||`<p class="empty">${h(t('libraryNoBooks'))}</p>`}</div></div>`;
}
